sys_script_include.script:
var AttendeeUtilsClient = Class.create();
AttendeeUtilsClient.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    createAttendee: function() {
        var eventId = this.getParameter('sysparm_eventId');
        var firstName = this.getParameter('sysparm_firstName');
        var lastName = this.getParameter('sysparm_lastName');
        var email = this.getParameter('sysparm_email');
        var contactNumber = this.getParameter('sysparm_contactNumber');

        var newAttendee = new GlideRecord('x_1790227_event_ma_attendee');
        newAttendee.initialize();
        newAttendee.u_first_name = firstName;
        newAttendee.u_last_name = lastName;
        newAttendee.u_email = email;
        newAttendee.u_contact_number = contactNumber;
        newAttendee.u_event_id = eventId;

        var inserted = newAttendee.insert();
        if (inserted) {
            return 'success';
        }
        return 'failure';
    },

isAttendeeRegistered: function() {
        var email = this.getParameter('sysparm_email');
        var eventId = this.getParameter('sysparm_event_id');

        var gr = new GlideRecord('x_1790227_event_ma_attendee');
        gr.addQuery('u_email', email);
        gr.addQuery('u_event_id.number', eventId);
        gr.query();

        while (gr.next()) {
            return 'Attendee is Registerd';
        }
        return 'Attendee is not registerd';
    },

    getAttendeeDetailsById: function() {
        var attendeeId = this.getParameter('sysparm_attendee_id');
        var gr = new GlideRecord('x_1790227_event_ma_attendee');
        gr.addQuery('number', attendeeId);
        gr.query();

        var result = [];
        while (gr.next()) {
            result.push(
                'Name: ' + gr.getValue('u_first_name') + ' ' + gr.getValue('u_last_name') +
                ', Email: ' + gr.getValue('u_email') +
                ', Contact: ' + gr.getValue('u_contact_number') +
                ', Event: ' + gr.getDisplayValue('u_event_id')
            );
        }
        return result.length ? result.join('\n') : 'Attendee not found';
    },

    getAttendeesByEventId: function() {
        var eventId = this.getParameter('sysparm_event_id');
        var gr = new GlideRecord('x_1790227_event_ma_attendee');
        gr.addQuery('u_event_id.number', eventId);
        gr.query();

        var result = [];
        while (gr.next()) {
            result.push(
                gr.getValue('u_first_name') + ' ' + gr.getValue('u_last_name') +
                ' (' + gr.getValue('u_email') + ')'
            );
        }
        return result.length ? result.join('\n') : 'No attendees found';
    },

    type: 'AttendeeUtilsClient'
});
